Here is the commit message:
nstree: tighten permission checks for listing

Even privileged services should not necessarily be able to see other
privileged service's namespaces so they can't leak information to each
other. Use may_see_all_namespaces() helper that centralizes this policy
until the nstree adapts.

Link: https://patch.msgid.link/20260226-work-visibility-fixes-v1-3-d2c2853313bd@kernel.org
Fixes: 76b6f5dfb3fd ("nstree: add listns()")
Reviewed-by: Jeff Layton <jlayton@kernel.org>
Cc: stable@kernel.org # v6.19+
Signed-off-by: Christian Brauner <brauner@kernel.org>

Here is the root cause:
The original permission checks in `may_list_ns()` and `do_listns_userns()` allowed privileged services (e.g., those with `CAP_SYS_ADMIN` in a user namespace) to list namespaces of other services without restriction, enabling information leakage between equally privileged but isolated services. The overly permissive `ns_capable_noaudit()` calls lacked centralized policy enforcement to prevent cross-service namespace visibility.

Here is the patch:

 static inline bool __must_check may_list_ns(const struct klistns *kls,
 					    struct ns_common *ns)
 {
-	if (kls->user_ns) {
-		if (kls->userns_capable)
-			return true;
-	} else {
-		struct ns_common *owner;
-		struct user_namespace *user_ns;
-
-		owner = ns_owner(ns);
-		if (owner)
-			user_ns = to_user_ns(owner);
-		else
-			user_ns = &init_user_ns;
-		if (ns_capable_noaudit(user_ns, CAP_SYS_ADMIN))
-			return true;
-	}
-
-	if (is_current_namespace(ns))
+	if (kls->user_ns && kls->userns_capable)
 		return true;
-
-	if (ns->ns_type != CLONE_NEWUSER)
-		return false;
-
-	if (ns_capable_noaudit(to_user_ns(ns), CAP_SYS_ADMIN))
+	if (is_current_namespace(ns))
 		return true;
-
-	return false;
+	return may_see_all_namespaces();
 }


 static ssize_t do_listns_userns(struct klistns *kls)
 {
 	u64 __user *ns_ids = kls->uns_ids;
 	size_t nr_ns_ids = kls->nr_ns_ids;
 	struct ns_common *ns = NULL, *first_ns = NULL, *prev = NULL;
 	const struct list_head *head;
 	ssize_t ret;

 	VFS_WARN_ON_ONCE(!kls->user_ns_id);

 	if (kls->user_ns_id == LISTNS_CURRENT_USER)
 		ns = to_ns_common(current_user_ns());
 	else if (kls->user_ns_id)
 		ns = lookup_ns_id(kls->user_ns_id, CLONE_NEWUSER);
 	if (!ns)
 		return -EINVAL;
 	kls->user_ns = to_user_ns(ns);

 	/*
 	 * Use the rbtree to find the first namespace we care about and
 	 * then use it's list entry to iterate from there.
 	 */
 	if (kls->last_ns_id) {
 		kls->first_ns = lookup_ns_owner_at(kls->last_ns_id + 1, ns);
 		if (!kls->first_ns)
 			return -ENOENT;
 		first_ns = kls->first_ns;
 	}

 	ret = 0;
 	head = &to_ns_common(kls->user_ns)->ns_owner_root.ns_list_head;
-	kls->userns_capable = ns_capable_noaudit(kls->user_ns, CAP_SYS_ADMIN);
+	kls->userns_capable = may_see_all_namespaces();

 	rcu_read_lock();

 	if (!first_ns)
 		first_ns = list_entry_rcu(head->next, typeof(*first_ns), ns_owner_node.ns_list_entry);

 	ns = first_ns;
 	list_for_each_entry_from_rcu(ns, head, ns_owner_node.ns_list_entry) {
 		struct ns_common *valid;

 		if (!nr_ns_ids)
 			break;

 		valid = legitimize_ns(kls, ns);
 		if (!valid)
 			continue;

 		rcu_read_unlock();

 		ns_put(prev);
 		prev = valid;

 		if (put_user(valid->ns_id, ns_ids + ret)) {
 			ns_put(prev);
 			return -EFAULT;
 		}

 		nr_ns_ids--;
 		ret++;

 		rcu_read_lock();
 	}

 	rcu_read_unlock();
 	ns_put(prev);
 	return ret;
 }



